package school.chacademia.housing;
import java.nio.file.*;import java.sql.*;import java.util.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;import school.magiccodex.protocol.HousingSearchProtocol;import school.magiccodex.protocol.HousingProtocol.Person;
class HousingDirectoryTest {
 @TempDir Path temp;Path local;final UUID viewer=UUID.randomUUID(),of=UUID.randomUUID(),on=UUID.randomUUID(),ff=UUID.randomUUID(),nf=UUID.randomUUID();
 Path folder(String server){return temp.resolve("network").resolve(server).resolve("plugins/MagicCodexBridge");}
 Connection db(String server)throws Exception{return DriverManager.getConnection("jdbc:sqlite:"+folder(server).resolve("friends.db"));}
 void nick(Connection c,UUID id,String name)throws Exception{try(var s=c.prepareStatement("INSERT INTO nicknames VALUES(?,?,1)")){s.setString(1,id.toString());s.setString(2,name);s.executeUpdate();}}
 @BeforeEach void seed()throws Exception{Class.forName("org.sqlite.JDBC");for(String server:List.of("school","wild","arena")){Files.createDirectories(folder(server));try(var c=db(server)){c.createStatement().execute("CREATE TABLE nicknames(owner TEXT PRIMARY KEY,nickname TEXT,revision INT)");c.createStatement().execute("CREATE TABLE friends(owner TEXT,target TEXT)");}}local=folder("school");try(var c=db("school")){nick(c,of,"나온라인친구");nick(c,ff,"다오프라인친구");c.createStatement().execute("INSERT INTO friends VALUES('"+viewer+"','"+of+"'),('"+viewer+"','"+ff+"')");}try(var c=db("wild")){nick(c,of,"나온라인친구");nick(c,on,"가온라인유저");}try(var c=db("arena")){nick(c,nf,"라오프라인유저");}}
 @Test void actualSqlRanksGlobalOnlineThenFriendStatusAndDeduplicatesUuid()throws Exception{try(var d=new HousingDirectory(local)){var page=d.search(viewer,"",0,Set.of(of,on));assertEquals(List.of(of,on,ff,nf),page.hits().stream().map(HousingDirectory.Hit::id).toList());assertFalse(page.more());assertEquals(List.of(nf),d.search(viewer,"라오프라인",0,Set.of()).hits().stream().map(HousingDirectory.Hit::id).toList());assertEquals(1,d.search(viewer,"나온라인",0,Set.of()).hits().size());}try(var c=db("school");var r=c.createStatement().executeQuery("SELECT COUNT(*) FROM nicknames")){assertTrue(r.next());assertEquals(2,r.getInt(1));}}
 @Test void allRegisteredUsersAreServerPagedWithoutDuplicatesOrInventedAccounts()throws Exception{try(var c=db("arena")){c.setAutoCommit(false);for(int i=0;i<607;i++)nick(c,UUID.randomUUID(),String.format("등록학생%04d",i));c.commit();}try(var d=new HousingDirectory(local)){var seen=new HashSet<UUID>();int page=0;boolean more;do{var slice=d.search(viewer,"",page++,Set.of(of,on));assertTrue(slice.hits().size()<=30);for(var row:slice.hits())assertTrue(seen.add(row.id()));more=slice.more();}while(more);assertEquals(611,seen.size());assertTrue(d.search(viewer,"임의미등록계정",0,Set.of()).hits().isEmpty());}}
 @Test void independentRevisionOrEnglishSnapshotsNeverResolveANameConflict()throws Exception{try(var c=db("wild")){c.createStatement().execute("UPDATE nicknames SET nickname='충돌이름',revision=999 WHERE owner='"+of+"'");}try(var d=new HousingDirectory(local)){assertThrows(Exception.class,()->d.search(viewer,"",0,Set.of()));}}
 @Test void friendshipIsReadFromExactLocalBridgeDomainAndCannotGrantFromOtherStore()throws Exception{try(var c=db("wild")){c.createStatement().execute("INSERT INTO friends VALUES('"+viewer+"','"+nf+"')");}try(var d=new HousingDirectory(local)){assertEquals(Set.of(of,ff),d.friends(viewer));assertFalse(d.friends(viewer).contains(nf));}assertFalse(HousingVisitPolicy.allowed(viewer,nf,false,false));assertFalse(HousingVisitPolicy.allowed(viewer,nf,false,null));assertTrue(HousingVisitPolicy.allowed(viewer,nf,false,true));assertTrue(HousingVisitPolicy.allowed(viewer,nf,true,null));assertTrue(HousingVisitPolicy.allowed(viewer,viewer,false,null));}
 @Test void additiveWireCarriesGenerationPageFriendStatusAndRejectsInvalidInput(){var q=new HousingSearchProtocol.Query(123,4,"한글");assertEquals(q,HousingSearchProtocol.query(HousingSearchProtocol.encode(q)));var user=new HousingSearchProtocol.User(new Person(of,"한글",-1,"",false),true,true,8);var page=new HousingSearchProtocol.Page(123,4,true,List.of(user),"");assertEquals(page,HousingSearchProtocol.page(HousingSearchProtocol.encode(page)));assertThrows(IllegalArgumentException.class,()->new HousingSearchProtocol.Query(1,-1,""));assertThrows(IllegalArgumentException.class,()->new HousingSearchProtocol.Query(1,0,"x".repeat(33)));assertThrows(IllegalArgumentException.class,()->HousingSearchProtocol.page(HousingSearchProtocol.encode(new HousingSearchProtocol.Page(1,0,false,List.of(user,user),""))));}
}
